import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, phone as phoneToken } from "./tokens.stylex";
import { rs } from "./rs";

const phone = "@media (max-width: 640px)" as typeof phoneToken;

export interface ToastOptions {
  description?: React.ReactNode;
}

interface ToastItem {
  id: number;
  title: React.ReactNode;
  description?: React.ReactNode;
}

let nextId = 1;
const listeners = new Set<(item: ToastItem) => void>();

/** Fire a toast from anywhere; a mounted <Toaster /> renders it. */
export function toast(title: React.ReactNode, options?: ToastOptions): void {
  const item: ToastItem = { id: nextId++, title, description: options?.description };
  listeners.forEach((listener) => listener(item));
}

export interface ToasterProps extends React.HTMLAttributes<HTMLDivElement> {
  /** How long a toast stays, in milliseconds. */
  duration?: number;
}

const toastIn = stylex.keyframes({
  from: { opacity: 0 },
  to: { opacity: 1 },
});

const styles = stylex.create({
  stack: {
    position: "fixed",
    bottom: {
      default: 20,
      [phone]: 0,
    },
    right: {
      default: 20,
      [phone]: 0,
    },
    left: {
      default: null,
      [phone]: 0,
    },
    zIndex: 300,
    display: "flex",
    flexDirection: "column",
    alignItems: {
      default: "flex-end",
      [phone]: "stretch",
    },
    gap: {
      default: 8,
      [phone]: 0,
    },
  },
  toast: {
    display: "flex",
    alignItems: "flex-start",
    gap: 10,
    backgroundColor: raster.paper,
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: {
      default: raster.radius,
      [phone]: 0,
    },
    boxShadow: {
      default: "0 8px 24px rgba(0,0,0,0.06)",
      [phone]: "none",
    },
    paddingTop: {
      default: 10,
      [phone]: 16,
    },
    paddingInline: {
      default: 14,
      [phone]: 20,
    },
    paddingBottom: {
      default: 10,
      [phone]: "calc(16px + env(safe-area-inset-bottom, 0px))",
    },
    maxWidth: {
      default: 340,
      [phone]: "none",
    },
    width: {
      default: null,
      [phone]: "100%",
    },
    animationName: {
      default: toastIn,
      "@media (prefers-reduced-motion: reduce)": "none",
    },
    animationDuration: raster.durationConfirm,
    animationTimingFunction: raster.ease,
  },
  title: {
    display: "block",
    fontSize: {
      default: 13,
      [phone]: 16,
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.ink,
  },
  body: {
    fontSize: {
      default: 12.5,
      [phone]: 15,
    },
    lineHeight: 1.5,
    letterSpacing: "-0.01em",
    color: raster.gray,
    marginTop: {
      default: 1,
      [phone]: 4,
    },
    marginBottom: 0,
    marginInline: 0,
  },
});

export function Toaster({ duration = 4000, className, style, ...props }: ToasterProps) {
  const [items, setItems] = React.useState<ToastItem[]>([]);

  React.useEffect(() => {
    const add = (item: ToastItem) => {
      setItems((current) => [...current, item]);
      setTimeout(() => {
        setItems((current) => current.filter((i) => i.id !== item.id));
      }, duration);
    };
    listeners.add(add);
    return () => {
      listeners.delete(add);
    };
  }, [duration]);

  const stack = rs(["rs-toasts", className], styles.stack);
  return (
    <div {...props} className={stack.className} style={{ ...stack.style, ...style }} role="status" aria-live="polite">
      {items.map((item) => {
        const card = rs(["rs-toast"], styles.toast);
        const heading = rs(["rs-toast-title"], styles.title);
        const body = rs(["rs-toast-body"], styles.body);
        return (
          <div key={item.id} className={card.className} style={card.style}>
            <div>
              <span className={heading.className} style={heading.style}>
                {item.title}
              </span>
              {item.description != null && (
                <p className={body.className} style={body.style}>
                  {item.description}
                </p>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

